import React from "react";
import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import { Disclaimer } from "../src/components/Disclaimer";

describe("Disclaimer Component", () => {
  it("renders the mandatory non-binder copy exactly", () => {
    render(<Disclaimer />);
    const expectedCopy =
      "Estimates are generated by a machine learning model for informational purposes only. This does not constitute an official quote, offer, or insurance binder. Actual premiums are determined by underwriting.";
    
    expect(screen.getByText(expectedCopy)).toBeDefined();
  });
});

